//! The Rust arm of the buffer-pool kind's lending contract (docs/adr/0111 D4):
//! every scenario of `tests/forge/conformance/buffer_pool/pool_contract.json`
//! runs against each pool its `pools` list names, generated by `build.rs` Step 10
//! from the documents beside it. The C11 arm
//! (`backends/c/forge-runtime/tests/conformance/buffer_pool_test.c`) runs the same
//! scenarios against the same documents, so the two pools are held to one
//! contract: the run-time count and length, the caller's storage, the
//! generational index and its reclaim, the headroom and the prefixed take, and
//! a received slot lent to the events of its frame.

mod pools {
    // The generated modules open with `#![allow(...)]`, which `build.rs` strips
    // because an inner attribute cannot sit at an `include!` point; each module
    // carries them as outer attributes.
    #[allow(clippy::all, unused_imports, unused_variables, dead_code)]
    pub mod owner {
        include!(concat!(env!("OUT_DIR"), "/pool_conformance_owner.rs"));
    }
    #[allow(clippy::all, unused_imports, unused_variables, dead_code)]
    pub mod shared {
        include!(concat!(env!("OUT_DIR"), "/pool_conformance_shared.rs"));
    }
}

use std::path::PathBuf;

use serde_json::Value;

fn contract() -> Value {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../tests/forge/conformance/buffer_pool/pool_contract.json");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("{} is not JSON: {e}", path.display()))
}

fn field<'a>(value: &'a Value, key: &str, context: &str) -> &'a Value {
    value
        .get(key)
        .unwrap_or_else(|| panic!("{context}: missing \"{key}\""))
}

fn number(value: &Value, key: &str, context: &str) -> usize {
    let n = field(value, key, context)
        .as_u64()
        .unwrap_or_else(|| panic!("{context}: \"{key}\" is not a number"));
    usize::try_from(n).unwrap_or_else(|_| panic!("{context}: \"{key}\" does not fit"))
}

fn text<'a>(value: &'a Value, key: &str, context: &str) -> &'a str {
    field(value, key, context)
        .as_str()
        .unwrap_or_else(|| panic!("{context}: \"{key}\" is not a string"))
}

fn bytes(value: &Value, key: &str, context: &str) -> Vec<u8> {
    field(value, key, context)
        .as_array()
        .unwrap_or_else(|| panic!("{context}: \"{key}\" is not a list"))
        .iter()
        .map(|b| {
            b.as_u64()
                .and_then(|b| u8::try_from(b).ok())
                .unwrap_or_else(|| panic!("{context}: \"{key}\" holds a value that is no byte"))
        })
        .collect()
}

/// Storage a caller holds, on the documents' 16-byte alignment, large enough
/// for every span a scenario cuts and the offset it starts at.
#[repr(C, align(16))]
struct Arena([u8; 272]);

/// Each pool module's scenario runner: the same body, written once, compiled
/// against each module's own types.
macro_rules! pool_runner {
    ($runner:ident, $module:ident, $Pool:ident) => {
        mod $runner {
            use super::pools::$module::{
                $Pool, CpuMut, CpuRef, LendRefused, PoolRefused, Slot, SlotIndex, SlotStore,
                TakeRefused,
            };
            use super::{bytes, field, number, text, Arena};
            use serde_json::Value;

            /// A handle a register holds: one the CPU may write, or one
            /// holding a received frame.
            enum Held {
                Mut(Slot<CpuMut>),
                Ref(Slot<CpuRef>),
            }

            fn lend_outcome(refused: LendRefused) -> &'static str {
                match refused {
                    LendRefused::Exhausted => "exhausted",
                    LendRefused::Length => "length",
                    LendRefused::Headroom => "headroom",
                }
            }

            fn pool_outcome(refused: PoolRefused) -> &'static str {
                match refused {
                    PoolRefused::Count => "count",
                    PoolRefused::Length => "length",
                    PoolRefused::Short => "short",
                    PoolRefused::Misaligned => "misaligned",
                }
            }

            pub fn run(scenario: &Value) {
                let id = text(scenario, "id", "a scenario");
                let make = field(scenario, "make", id);
                let expect = text(scenario, "expect", id);
                let steps = field(scenario, "steps", id)
                    .as_array()
                    .unwrap_or_else(|| panic!("{id}: \"steps\" is not a list"));
                if let Some(over) = make.get("over") {
                    let mut arena = Arena([0u8; 272]);
                    let offset = number(over, "offset", id);
                    let span = number(over, "span", id);
                    let made = $Pool::over(
                        &mut arena.0[offset..offset + span],
                        number(over, "count", id),
                        number(over, "len", id),
                    );
                    match made {
                        Ok(pool) => {
                            assert_eq!(expect, "ok", "{id}: the pool over the span was made");
                            steps_of(&pool, id, steps);
                        }
                        Err(refused) => assert_eq!(pool_outcome(refused), expect, "{id}"),
                    }
                } else {
                    match $Pool::with_count(number(make, "count", id)) {
                        Ok(pool) => {
                            assert_eq!(expect, "ok", "{id}: the pool of the count was made");
                            steps_of(&pool, id, steps);
                        }
                        Err(refused) => assert_eq!(pool_outcome(refused), expect, "{id}"),
                    }
                }
            }

            fn steps_of(pool: &$Pool<impl SlotStore>, id: &str, steps: &[Value]) {
                let mut held: Vec<Option<Held>> = (0..8).map(|_| None).collect();
                let mut indices: Vec<Option<SlotIndex>> = vec![None; 8];
                let mut sent: Vec<u8> = Vec::new();
                let absent = Value::Null;
                for (n, step) in steps.iter().enumerate() {
                    let context = format!("{id} step {n}");
                    let context = context.as_str();
                    let op = text(step, "op", context);
                    let slot_reg = || number(step, "slot", context);
                    let index_reg = || number(step, "index", context);
                    let out_reg = || number(step, "out", context);
                    // A step that only moves bytes or names an index answers
                    // nothing, and the contract gives it no `expect`; every other
                    // step must give one.
                    let expect = match op {
                        "write" | "read" | "sent" | "index" | "into_index" => &absent,
                        _ => field(step, "expect", context),
                    };
                    let index_at = |indices: &[Option<SlotIndex>]| {
                        indices[index_reg()]
                            .unwrap_or_else(|| panic!("{context}: the index register is empty"))
                    };
                    match op {
                        "count" => {
                            assert_eq!(Some(pool.count() as u64), expect.as_u64(), "{context}")
                        }
                        "slot_len" => {
                            assert_eq!(Some(pool.slot_len() as u64), expect.as_u64(), "{context}")
                        }
                        "free" => {
                            assert_eq!(Some(pool.free_count() as u64), expect.as_u64(), "{context}")
                        }
                        "violations" => assert_eq!(
                            Some(u64::from(pool.ownership_violations())),
                            expect.as_u64(),
                            "{context}"
                        ),
                        "refused_prefixes" => assert_eq!(
                            Some(u64::from(pool.refused_prefixes())),
                            expect.as_u64(),
                            "{context}"
                        ),
                        "acquire" => {
                            let got = pool.pool_acquire_for_encode(
                                number(step, "len", context),
                                number(step, "headroom", context),
                            );
                            match got {
                                Ok(slot) => {
                                    assert_eq!(expect.as_str(), Some("ok"), "{context}");
                                    held[out_reg()] = Some(Held::Mut(slot));
                                }
                                Err(refused) => {
                                    assert_eq!(
                                        Some(lend_outcome(refused)),
                                        expect.as_str(),
                                        "{context}"
                                    )
                                }
                            }
                        }
                        "receive" => {
                            let wrote = bytes(step, "bytes", context);
                            match pool.link_arm_rx(number(step, "len", context)) {
                                Ok(armed) => {
                                    assert_eq!(expect.as_str(), Some("ok"), "{context}");
                                    let position = armed.index().slot as usize;
                                    let at = armed.dma_armed_rx_ptr(pool);
                                    // SAFETY: standing in for the peripheral: the
                                    // slot is armed for it, and nothing else reads
                                    // or writes it until the completion below.
                                    unsafe {
                                        for (i, b) in wrote.iter().enumerate() {
                                            at.add(i).write(*b);
                                        }
                                        armed.dma_start_rx(pool);
                                    }
                                    // SAFETY: standing in for the RX-complete IRQ.
                                    let frame = unsafe { pool.rx_complete(position) }
                                        .unwrap_or_else(|| {
                                            panic!("{context}: the completion yields the frame")
                                        });
                                    held[out_reg()] = Some(Held::Ref(frame));
                                }
                                Err(refused) => {
                                    assert_eq!(
                                        Some(lend_outcome(refused)),
                                        expect.as_str(),
                                        "{context}"
                                    )
                                }
                            }
                        }
                        "capacity" => {
                            let length = match held[slot_reg()].as_ref() {
                                Some(Held::Mut(slot)) => slot.read(pool).len(),
                                Some(Held::Ref(slot)) => slot.read(pool).len(),
                                None => panic!("{context}: the handle register is empty"),
                            };
                            assert_eq!(Some(length as u64), expect.as_u64(), "{context}");
                        }
                        "write" => {
                            let wrote = bytes(step, "bytes", context);
                            match held[slot_reg()].as_mut() {
                                Some(Held::Mut(slot)) => {
                                    slot.write(pool)[..wrote.len()].copy_from_slice(&wrote)
                                }
                                _ => panic!("{context}: the register holds no writable handle"),
                            }
                        }
                        "read" => {
                            let want = bytes(step, "bytes", context);
                            let got = match held[slot_reg()].as_ref() {
                                Some(Held::Mut(slot)) => slot.read(pool)[..want.len()].to_vec(),
                                Some(Held::Ref(slot)) => slot.read(pool)[..want.len()].to_vec(),
                                None => panic!("{context}: the handle register is empty"),
                            };
                            assert_eq!(got, want, "{context}");
                        }
                        "arm_tx" => {
                            let Some(Held::Mut(slot)) = held[slot_reg()].take() else {
                                panic!("{context}: the register holds no writable handle");
                            };
                            match slot.link_arm_tx(pool, number(step, "frame", context)) {
                                Ok(index) => {
                                    assert_eq!(expect.as_str(), Some("ok"), "{context}");
                                    indices[out_reg()] = Some(index);
                                }
                                Err(slot) => {
                                    assert_eq!(expect.as_str(), Some("refused"), "{context}");
                                    held[slot_reg()] = Some(Held::Mut(slot));
                                }
                            }
                        }
                        "return" => {
                            assert_eq!(expect.as_str(), Some("ok"), "{context}");
                            match held[slot_reg()].take() {
                                Some(Held::Mut(slot)) => slot.pool_return(pool),
                                Some(Held::Ref(slot)) => slot.pool_return(pool),
                                None => panic!("{context}: the handle register is empty"),
                            }
                        }
                        "index" => {
                            let index = match held[slot_reg()].as_ref() {
                                Some(Held::Mut(slot)) => slot.index(),
                                Some(Held::Ref(slot)) => slot.index(),
                                None => panic!("{context}: the handle register is empty"),
                            };
                            indices[out_reg()] = Some(index);
                        }
                        "into_index" => {
                            let index = match held[slot_reg()].take() {
                                Some(Held::Mut(slot)) => slot.into_index(pool),
                                Some(Held::Ref(slot)) => slot.into_index(pool),
                                None => panic!("{context}: the handle register is empty"),
                            };
                            indices[out_reg()] = Some(index);
                        }
                        "reclaim" => {
                            let index = index_at(&indices);
                            let rebuilt = match text(step, "state", context) {
                                "cpu-mut" => pool.reclaim::<CpuMut>(index).map(Held::Mut),
                                "cpu-ref" => pool.reclaim::<CpuRef>(index).map(Held::Ref),
                                other => panic!("{context}: no handle is held in {other}"),
                            };
                            assert_eq!(
                                expect.as_str(),
                                Some(if rebuilt.is_some() { "ok" } else { "refused" }),
                                "{context}"
                            );
                            if rebuilt.is_some() {
                                held[out_reg()] = rebuilt;
                            }
                        }
                        "generation" => assert_eq!(
                            Some(u64::from(index_at(&indices).generation)),
                            expect.as_u64(),
                            "{context}"
                        ),
                        "take" => {
                            let prefix = bytes(step, "prefix", context);
                            // SAFETY: this test is the driver, and nothing writes
                            // the slot until the completion a later step makes.
                            let taken = unsafe { pool.take_prefixed(index_at(&indices), &prefix) };
                            match taken {
                                Ok(span) => {
                                    assert_eq!(expect.as_str(), Some("ok"), "{context}");
                                    assert_eq!(span.len, number(step, "len", context), "{context}");
                                    // SAFETY: the span is the slot's, which nothing
                                    // writes while it is busy.
                                    sent =
                                        unsafe { core::slice::from_raw_parts(span.ptr, span.len) }
                                            .to_vec();
                                }
                                Err(TakeRefused::Stale) => {
                                    assert_eq!(expect.as_str(), Some("stale"), "{context}")
                                }
                                Err(TakeRefused::PrefixTooWide) => {
                                    assert_eq!(
                                        expect.as_str(),
                                        Some("prefix-too-wide"),
                                        "{context}"
                                    )
                                }
                            }
                        }
                        "sent" => assert_eq!(sent, bytes(step, "bytes", context), "{context}"),
                        "complete_tx" => {
                            let position = index_at(&indices).slot as usize;
                            // SAFETY: standing in for the TX-complete IRQ.
                            let done = unsafe { pool.tx_complete(position) };
                            assert_eq!(Some(done), expect.as_bool(), "{context}");
                        }
                        "lend" => {
                            let Some(Held::Ref(slot)) = held[slot_reg()].take() else {
                                panic!("{context}: the register holds no received frame");
                            };
                            let holds = u32::try_from(number(step, "holds", context))
                                .unwrap_or_else(|_| panic!("{context}: holds do not fit"));
                            match slot.lend(pool, holds) {
                                Ok(index) => {
                                    assert_eq!(expect.as_str(), Some("ok"), "{context}");
                                    indices[out_reg()] = Some(index);
                                }
                                Err(slot) => {
                                    assert_eq!(expect.as_str(), Some("refused"), "{context}");
                                    held[slot_reg()] = Some(Held::Ref(slot));
                                }
                            }
                        }
                        "hold" => assert_eq!(
                            Some(pool.hold(index_at(&indices))),
                            expect.as_bool(),
                            "{context}"
                        ),
                        "release" => {
                            assert_eq!(
                                Some(pool.release(index_at(&indices))),
                                expect.as_bool(),
                                "{context}"
                            )
                        }
                        "lent" => assert_eq!(
                            pool.lent(index_at(&indices)).map(|span| span.len as u64),
                            expect.as_u64(),
                            "{context}"
                        ),
                        other => panic!("{context}: unknown op {other}"),
                    }
                }
            }
        }
    };
}

pool_runner!(owner_runner, owner, PoolConformanceOwner);
pool_runner!(shared_runner, shared, PoolConformanceShared);

fn scenarios() -> Vec<Value> {
    let contract = contract();
    assert_eq!(
        contract.get("version").and_then(Value::as_u64),
        Some(1),
        "this arm reads version 1 of the pool contract"
    );
    let pools: Vec<&str> = field(&contract, "pools", "the contract")
        .as_array()
        .expect("\"pools\" is a list")
        .iter()
        .map(|p| p.as_str().expect("a pool is named"))
        .collect();
    assert_eq!(
        pools,
        ["pool_conformance_owner", "pool_conformance_shared"],
        "the pools this arm generates are the pools the contract names"
    );
    let scenarios = field(&contract, "scenarios", "the contract")
        .as_array()
        .expect("\"scenarios\" is a list")
        .clone();
    assert!(
        !scenarios.is_empty(),
        "a contract with no scenarios checks nothing"
    );
    scenarios
}

#[test]
fn every_scenario_holds_for_the_owners_pool() {
    for scenario in scenarios() {
        owner_runner::run(&scenario);
    }
}

#[test]
fn every_scenario_holds_for_the_shared_pool() {
    for scenario in scenarios() {
        shared_runner::run(&scenario);
    }
}

/// docs/adr/0111 D4: a shared pool is `Sync` and an owner's is not, which is what
/// lets the link that holds an armed slot and the session that opens another
/// share the one, and keeps the other on the thread that holds the drive.
#[test]
fn a_shared_pool_is_sync() {
    fn is_sync<T: Sync>() {}
    is_sync::<pools::shared::PoolConformanceShared>();
}
